if !(IsFeatureImplemented(FEAT_GCIE) && IsFeatureImplemented(FEAT_AA64)) then
    Undefined();
elsif EffectivelyAtEL0InHost() || EffectivelyAtEL0NotInHost() then
    Undefined();
elsif PSTATE.EL == EL1 then
    if EL2Enabled() && HCR_EL2().IMO == '1' && IsFeatureImplemented(FEAT_GCIE_LEGACY) && ICH_VCTLR_EL2().V3 == '1' then
        Undefined();
    elsif EL2Enabled() && ICH_HFGRTR_EL2().ICC_CR0_EL1 == '0' then
        AArch64_SystemAccessTrap(EL2, 0x18);
    elsif EL2Enabled() && HCR_EL2().IMO == '1' then
        X{64}(t) = ICV_CR0_EL1();
    elsif HaveEL(EL3) then
        if EffectiveSCR_EL3_NS() == '0' then
            X{64}(t) = ICC_CR0_EL1_S();
        elsif IsFeatureImplemented(FEAT_RME) && EffectiveSCR_EL3_NSE() == '1' && EffectiveSCR_EL3_NS() == '1' then
            X{64}(t) = ICC_CR0_EL1_RL();
        elsif (!IsFeatureImplemented(FEAT_RME) || EffectiveSCR_EL3_NSE() == '0') && EffectiveSCR_EL3_NS() == '1' then
            X{64}(t) = ICC_CR0_EL1_NS();
        else
            Undefined();
        end;
    else
        X{64}(t) = ICC_CR0_EL1();
    end;
elsif PSTATE.EL == EL2 then
    if HaveEL(EL3) then
        if EffectiveSCR_EL3_NS() == '0' then
            X{64}(t) = ICC_CR0_EL1_S();
        elsif IsFeatureImplemented(FEAT_RME) && EffectiveSCR_EL3_NSE() == '1' && EffectiveSCR_EL3_NS() == '1' then
            X{64}(t) = ICC_CR0_EL1_RL();
        elsif (!IsFeatureImplemented(FEAT_RME) || EffectiveSCR_EL3_NSE() == '0') && EffectiveSCR_EL3_NS() == '1' then
            X{64}(t) = ICC_CR0_EL1_NS();
        else
            Undefined();
        end;
    else
        X{64}(t) = ICC_CR0_EL1();
    end;
elsif PSTATE.EL == EL3 then
    if IsFeatureImplemented(FEAT_S1POE2) && FGDTState.E0 == '1' then
        AArch64_SystemAccessTrap(EL3, 0x18);
    else
        if EffectiveSCR_EL3_NS() == '0' then
            X{64}(t) = ICC_CR0_EL1_S();
        elsif IsFeatureImplemented(FEAT_RME) && EffectiveSCR_EL3_NSE() == '1' && EffectiveSCR_EL3_NS() == '1' then
            X{64}(t) = ICC_CR0_EL1_RL();
        elsif (!IsFeatureImplemented(FEAT_RME) || EffectiveSCR_EL3_NSE() == '0') && EffectiveSCR_EL3_NS() == '1' then
            X{64}(t) = ICC_CR0_EL1_NS();
        else
            Undefined();
        end;
    end;
end;

